    await page.goto('/');
    await page.waitForLoadState('domcontentloaded');

    // The link introspection recorded: href http://127.0.0.1:59666/, text 'Home', match 1 of those that are visible.
    let linkIndex = -1;
    await expect.poll(async () => (linkIndex = await page.locator('a').evaluateAll((links, wanted) => links
      .map((link, index) => ({ link, index }))
      .filter(({ link }) => (link as HTMLAnchorElement).href === wanted.url && (link.textContent ?? '').replace(/\s+/g, ' ').trim() === wanted.text)
      .filter(({ link }) => {
        const style = getComputedStyle(link);
        const box = link.getBoundingClientRect();
        return (style.display !== 'none' && style.visibility !== 'hidden' && box.width > 0 && box.height > 0) === wanted.visible;
      })
      .map(({ index }) => index)[wanted.occurrence] ?? -1, { url: 'http://127.0.0.1:59666/', text: 'Home', visible: true, occurrence: 0 })), { message: 'Home (a visible link to http://127.0.0.1:59666/) is not on the page' }).toBeGreaterThanOrEqual(0);
    const locator = page.locator('a').nth(linkIndex);
