// Reliability: page.route() failure-injection blocks each recorded dependency by (host, path) - see docs/decisions/phase-18-integration-mapping-decision-record.md Decision 4 (revised): every routable dependency gets a test by default, including redirects - each generated test runs in its own isolated Playwright context with no shared storageState today, so blocking one cannot affect any other test in the run. That changes once Phase 20 introduces a run-wide cached storageState; the fix at that point must be pinpointed to the specific dependency matching the configured login URL, not a blanket kind-wide exclusion, and isn't built yet. Cookie-kind dependencies are recorded by introspect but have no generated test here for a separate, mechanical reason - a cookie isn't a routable network request. A form-action test also submits its form once blocked (requestSubmit()) so the block is actually exercised, not just present during an inert page load - still read-only from the target's point of view, since the aborted request never leaves the browser.
test.describe('Reliability Coverage', () => {
  test('TFRL-001: dependency failure injection: 127.0.0.1:59666 [xhr-fetch]', { annotation: { type: 'gate', description: 'read-only' } }, async ({ page }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (error) => pageErrors.push(error.message));

    await page.route(
      (url) => url.host === '127.0.0.1:59666' && url.pathname === '/api/status',
      (route) => route.abort('failed')
    );

    const response = await page.goto('/', { waitUntil: 'domcontentloaded' });
    await page.waitForLoadState('networkidle', { timeout: 10000 }).catch(() => {});

    await page.waitForLoadState('networkidle', { timeout: 10000 }).catch(() => {});

    expect(response?.status() ?? 0, 'the page itself should still respond with 127.0.0.1:59666/api/status blocked').toBeLessThan(500);
    await expect(page.locator('body'), 'the page should still render a body, not a blank crash screen').toBeVisible();
    expect(pageErrors, 'no uncaught page errors after blocking 127.0.0.1:59666/api/status: ' + pageErrors.join('; ')).toEqual([]);
  });

  test('TFRL-002: dependency failure injection: 127.0.0.1:59666 [form-action]', { annotation: { type: 'gate', description: 'read-only' } }, async ({ page }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (error) => pageErrors.push(error.message));

    await page.route(
      (url) => url.host === '127.0.0.1:59666' && url.pathname === '/login',
      (route) => route.abort('failed')
    );

    const response = await page.goto('/login', { waitUntil: 'domcontentloaded' });
    await page.waitForLoadState('networkidle', { timeout: 10000 }).catch(() => {});

    const form = page.locator('form[action="/login"]').first();
    if (await form.count() > 0) {
      await form.evaluate((el) => (el as HTMLFormElement).requestSubmit());
    }

    await page.waitForLoadState('networkidle', { timeout: 10000 }).catch(() => {});

    expect(response?.status() ?? 0, 'the page itself should still respond with 127.0.0.1:59666/login blocked').toBeLessThan(500);
    await expect(page.locator('body'), 'the page should still render a body, not a blank crash screen').toBeVisible();
    expect(pageErrors, 'no uncaught page errors after blocking 127.0.0.1:59666/login: ' + pageErrors.join('; ')).toEqual([]);
  });
});

test.describe('Cookie and Session Coverage', () => {
  test('TFCS-001: session cookies set by the site expire and stay scoped to it', { annotation: { type: 'gate', description: 'read-only' } }, async ({ page, context }) => {
    await page.goto('/', { waitUntil: 'load' });
    const host = new URL(page.url()).hostname;
    const sessionName = /(^|[._-])(session|sess|sid|auth|token|jwt)([._-]|$)|^(jsessionid|phpsessid|asp\.net_sessionid|connect\.sid|rack\.session|laravel_session)$/i;
    const own = (await context.cookies()).filter((cookie) => {
      const domain = cookie.domain.replace(/^\./, '');
      return host === domain || host.endsWith('.' + domain);
    });
    const sessionCookies = own.filter((cookie) => sessionName.test(cookie.name));
    test.skip(sessionCookies.length === 0, 'no session cookie on the landing page (' + own.length + ' cookie(s) set by the site, none named like a session), so there is nothing to check');

    const problems: string[] = [];
    const maxDays = 30;
    for (const cookie of sessionCookies) {
      // expires is -1 for a cookie that ends with the browser session.
      if (cookie.expires > 0) {
        const days = (cookie.expires * 1000 - Date.now()) / 86400000;
        if (days > maxDays) problems.push('"' + cookie.name + '" stays valid for ' + Math.round(days) + ' days (more than ' + maxDays + ')');
      }
      const domain = cookie.domain.replace(/^\./, '');
      if (domain !== host) problems.push('"' + cookie.name + '" is set for ' + cookie.domain + ', so every subdomain of ' + domain + ' receives it, not only ' + host);
      else if (cookie.domain.startsWith('.')) test.info().annotations.push({ type: 'finding', description: 'session cookie "' + cookie.name + '" is set for ' + cookie.domain + ', so subdomains of ' + host + ' also receive it' });
    }
    expect(problems, 'session cookies that break expiry or scope: ' + problems.join('; ')).toEqual([]);
  });
});

// Database: each test saves a unique value through a discovered form, reloads, and checks the value is still shown. They submit real forms, so they are skipped unless TESTFORGE_INTERACTIVE=1 is set for the run (the "Run interactive tests" option).
test.describe('Database Coverage', () => {
  test('TFDB-001: persistence round trip: Note on /notes', { annotation: { type: 'gate', description: 'interactive' } }, async ({ page }) => {
    test.skip(process.env.TESTFORGE_INTERACTIVE !== '1', 'database round trip: saves data through a form on the live site, so it only runs when TESTFORGE_INTERACTIVE=1 is set for the run');

    // A value no earlier run can have saved, so finding it proves this run saved it.
    const value = `TestForge check ${Date.now()}`;
    await page.goto('/notes', { waitUntil: 'domcontentloaded' });
    const field = page.locator('[id="note"]');
    await expect(field, 'the "Note" field on /notes should be visible').toBeVisible();
    await field.fill(value);
    const form = field.locator('xpath=ancestor::form').first();
    await form.getByRole('button', { name: 'Save note' }).first().click();
    await page.waitForLoadState('domcontentloaded');

    await expect(page.getByText(value).first(), 'after saving, the page should show the value just entered in "Note" (' + value + '). If this site shows saved entries on a different page, this check does not fit it.').toBeVisible();
    await page.reload({ waitUntil: 'domcontentloaded' });
    await expect(page.getByText(value).first(), 'after a reload the value saved through "Note" (' + value + ') is gone: it was shown once but not persisted').toBeVisible();
  });
});

